import runpy
import unittest


def rodar():
    """Roda solucao.py do zero e devolve o que ele definiu."""
    return runpy.run_path("solucao.py")


class TestDuasListasLadoALado(unittest.TestCase):
    def test_juntar_por_posicao_pareia_os_itens(self):
        """juntar_por_posicao devolve um nome completo para cada par"""
        self.assertEqual(rodar()["juntar_por_posicao"](["ana", "bia"], ["souza", "luz"]), ["ana souza", "bia luz"])

    def test_juntar_por_posicao_com_uma_lista_so(self):
        """juntar_por_posicao para no fim da lista mais curta"""
        self.assertEqual(rodar()["juntar_por_posicao"](["ana"], ["souza", "luz"]), ["ana souza"])

    def test_juntar_por_posicao_com_listas_vazias(self):
        """juntar_por_posicao com duas listas vazias devolve lista vazia"""
        self.assertEqual(rodar()["juntar_por_posicao"]([], []), [])

